-- ── story 3-2b: why an adjustment pended, and which handheld asked ────────
-- Generated by drizzle-kit (the three column statements) and hand-amended
-- around the generated part: the fail-fast guard, the two CHECKs and the
-- post-migration probe (drizzle-kit is blind to CHECKs; `bun run
-- db:generate` afterwards reports "No schema changes").
--
-- Story 3-2b lets an operator REQUEST an adjustment (`stock.adjust.request`):
-- it always pends for the owner's approval, whatever its size — even when the
-- tenant has no threshold policy at all. Before this migration a pend could
-- not record that: `threshold_quantity_at_request` was NOT NULL (0044) and
-- nothing said why the row pended, or from which device (design review A1).
--
-- Additive, on `stock_adjustment_pendings` only:
--   * `threshold_quantity_at_request` DROPs NOT NULL — null = no policy row
--     when the request was force-pended. The 0044 `>= 0` CHECK still holds
--     for every non-null value (a CHECK admits NULL).
--   * `pend_reason text NOT NULL DEFAULT 'threshold'` — every existing row
--     backfills `threshold` through the default, which is correct: before
--     3-2b a row pended ONLY because |delta| exceeded its stored threshold.
--     Mirrored by `ADJUSTMENT_PEND_REASONS` (src/shared/db/schema.ts), pinned
--     TS ↔ DB by test/handheld-adjustment.spec.ts.
--   * `source_device_id uuid NULL` — the handheld that submitted the request
--     (null from the web, and on every pre-3-2b row). No FK (guide §3).
--
-- Lock cost: the ADD COLUMN with a constant default is metadata-only (PG11+,
-- no rewrite); the DROP NOT NULL is metadata-only; the two CHECKs scan the
-- table once under ACCESS EXCLUSIVE. The table holds only parked adjustments
-- awaiting an owner — small by construction — so they are added VALID rather
-- than NOT VALID + VALIDATE (guide §3). No index is built.

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'stock_adjustment_pendings' AND column_name = 'pend_reason'
	) THEN
		RAISE EXCEPTION 'migration 0090: stock_adjustment_pendings.pend_reason already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "stock_adjustment_pendings" ALTER COLUMN "threshold_quantity_at_request" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "stock_adjustment_pendings" ADD COLUMN "pend_reason" text DEFAULT 'threshold' NOT NULL;--> statement-breakpoint
ALTER TABLE "stock_adjustment_pendings" ADD COLUMN "source_device_id" uuid;--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only) ─────────────────────────
-- The vocabulary. The column is NOT NULL, so no NULL arm is needed (guide §3).
ALTER TABLE "stock_adjustment_pendings" ADD CONSTRAINT "stock_adjustment_pendings_pend_reason_check" CHECK (
	"pend_reason" IN ('threshold', 'approval-required')
);--> statement-breakpoint
-- A `threshold` pend names the threshold it crossed: only a forced
-- (`approval-required`) pend may carry a null threshold.
ALTER TABLE "stock_adjustment_pendings" ADD CONSTRAINT "stock_adjustment_pendings_threshold_reason_check" CHECK (
	"pend_reason" = 'approval-required' OR "threshold_quantity_at_request" IS NOT NULL
);--> statement-breakpoint
-- ── the post-migration assertion (the 0088 model) ─────────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT (guide §3).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	b uuid := gen_random_uuid();
	s uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: a pre-3-2b-shaped row (no pend_reason given → the
	-- default `threshold`, threshold present); a forced pend with no policy
	-- (null threshold) from a device; a forced pend under a policy.
	BEGIN
		INSERT INTO "stock_adjustment_pendings"
			("id","tenant_id","warehouse_id","bin_id","sku_id","quantity_milli","reason_code","note","occurred_at","requested_by","requested_at","threshold_quantity_at_request")
		VALUES (gen_random_uuid(), t, w, b, s, 5000, 'found', 'n', now(), u, now(), 2);
		IF NOT EXISTS (SELECT 1 FROM "stock_adjustment_pendings" WHERE "tenant_id" = t AND "pend_reason" = 'threshold' AND "source_device_id" IS NULL) THEN
			RAISE EXCEPTION 'migration 0090: a row without pend_reason did not default to threshold.';
		END IF;
		INSERT INTO "stock_adjustment_pendings"
			("id","tenant_id","warehouse_id","bin_id","sku_id","quantity_milli","reason_code","note","occurred_at","requested_by","requested_at","threshold_quantity_at_request","pend_reason","source_device_id")
		VALUES
			(gen_random_uuid(), t, w, b, s, -1000, 'damaged', 'n', now(), u, now(), NULL, 'approval-required', gen_random_uuid()),
			(gen_random_uuid(), t, w, b, s, 1000, 'found', 'n', now(), u, now(), 10, 'approval-required', NULL);
		RAISE EXCEPTION USING ERRCODE = 'P0090', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0090: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0090' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY['unknown reason', 'threshold pend without a threshold', 'negative threshold'] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown reason' THEN 'stock_adjustment_pendings_pend_reason_check'
			WHEN 'threshold pend without a threshold' THEN 'stock_adjustment_pendings_threshold_reason_check'
			ELSE 'stock_adjustment_pendings_threshold_check'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown reason' THEN
					INSERT INTO "stock_adjustment_pendings"
						("id","tenant_id","warehouse_id","bin_id","sku_id","quantity_milli","reason_code","note","occurred_at","requested_by","requested_at","threshold_quantity_at_request","pend_reason")
					VALUES (gen_random_uuid(), t, w, b, s, 1000, 'found', 'n', now(), u, now(), 0, 'forced');
				WHEN 'threshold pend without a threshold' THEN
					INSERT INTO "stock_adjustment_pendings"
						("id","tenant_id","warehouse_id","bin_id","sku_id","quantity_milli","reason_code","note","occurred_at","requested_by","requested_at","threshold_quantity_at_request","pend_reason")
					VALUES (gen_random_uuid(), t, w, b, s, 1000, 'found', 'n', now(), u, now(), NULL, 'threshold');
				WHEN 'negative threshold' THEN
					INSERT INTO "stock_adjustment_pendings"
						("id","tenant_id","warehouse_id","bin_id","sku_id","quantity_milli","reason_code","note","occurred_at","requested_by","requested_at","threshold_quantity_at_request","pend_reason")
					VALUES (gen_random_uuid(), t, w, b, s, 1000, 'found', 'n', now(), u, now(), -1, 'approval-required');
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0090: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "stock_adjustment_pendings" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0090: a probe row survived.';
	END IF;
END $$;
